import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Tenant API v1 — Team Chat","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Team Chat | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-team-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Team Chat | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-team-chat"}]]},"headers":[],"relativePath":"api/tenant-v1-team-chat.md","filePath":"api/tenant-v1-team-chat.md","lastUpdated":1788201759000}'),n={name:"api/tenant-v1-team-chat.md"};function r(c,e,i,d,h,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="tenant-api-v1-—-team-chat" tabindex="-1">Tenant API v1 — Team Chat <a class="header-anchor" href="#tenant-api-v1-—-team-chat" aria-label="Permalink to &quot;Tenant API v1 — Team Chat&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:team-chat</code>.</p><p>Named routes use the <code>tenant.team-chat.*</code> prefix. Absolute datetimes serialize as UTC ISO-8601 (<code>...Z</code>).</p><h2 id="authorization-notes" tabindex="-1">Authorization notes <a class="header-anchor" href="#authorization-notes" aria-label="Permalink to &quot;Authorization notes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Rule</th></tr></thead><tbody><tr><td>List / show conversation metadata</td><td><code>team-chat.view</code> — public channels are visible for join UX; private channels and DMs require membership</td></tr><tr><td>Message history, pins, downloads, search hits in a conversation</td><td>Membership (<code>viewMessages</code>) — public non-members cannot read history or files</td></tr><tr><td>Create channel</td><td><code>team-chat.channels.create</code> (channel create) or <code>team-chat.view</code> (DM / group DM)</td></tr><tr><td>Update channel metadata (name / description / visibility)</td><td>Channel <strong>creator</strong> only (<code>created_by</code>); membership required; not DMs</td></tr><tr><td>Permanently delete channel + history</td><td>Channel <strong>creator</strong> only; body <code>{ &quot;confirmation&quot;: &quot;&lt;exact channel name&gt;&quot; }</code>; <code>#general</code> cannot be deleted</td></tr><tr><td>Add/remove members</td><td>Channel moderator (owner/admin role on the membership) <strong>or</strong> <code>team-chat.channels.manage</code>; membership required; channels only</td></tr><tr><td>Post / react / pin / attach</td><td><code>team-chat.messages.create</code> + membership</td></tr><tr><td>Edit message</td><td>Author with <code>team-chat.messages.update</code>, or moderator with <code>team-chat.messages.delete</code>; membership required</td></tr><tr><td>Delete message</td><td>Author with <code>team-chat.messages.update</code> or <code>team-chat.messages.delete</code>, or moderator with <code>team-chat.messages.delete</code>; membership required</td></tr><tr><td>Upload attachment on a message</td><td>Own message (or <code>messages.delete</code> moderator) + create permission</td></tr></tbody></table><p>Member payloads omit <code>email</code>. Read/mute fields are only returned for the acting user’s own membership row.</p><h2 id="conversations" tabindex="-1">Conversations <a class="header-anchor" href="#conversations" aria-label="Permalink to &quot;Conversations&quot;">​</a></h2><h3 id="get-conversations" tabindex="-1">GET <code>/conversations</code> <a class="header-anchor" href="#get-conversations" aria-label="Permalink to &quot;GET `/conversations`&quot;">​</a></h3><p>Lists conversations the actor belongs to, plus public channels they can join. Ensures <code>#general</code> exists and that the actor is a member (cheap per-request join; full active-user join runs on module install only).</p><h3 id="post-conversations" tabindex="-1">POST <code>/conversations</code> <a class="header-anchor" href="#post-conversations" aria-label="Permalink to &quot;POST `/conversations`&quot;">​</a></h3><p>Create a channel, 1:1 DM, or group DM.</p><ul><li>Channel: <code>type=channel</code>, <code>name</code> (required), optional <code>visibility</code> (<code>public</code>|<code>private</code>), <code>description</code>, <code>member_ids</code></li><li>DM: <code>type=dm</code>, <code>user_id</code> (must not be the actor)</li><li>Group DM: <code>type=group_dm</code>, <code>user_ids</code> (array)</li></ul><p>Reuses an existing 1:1 DM for the same pair (<code>dm_key</code>).</p><h3 id="get-conversations-conversation" tabindex="-1">GET <code>/conversations/{conversation}</code> <a class="header-anchor" href="#get-conversations-conversation" aria-label="Permalink to &quot;GET `/conversations/{conversation}`&quot;">​</a></h3><p>Show metadata + members (names only). Non-members may view <strong>public</strong> channel metadata for join UX.</p><h3 id="patch-conversations-conversation" tabindex="-1">PATCH <code>/conversations/{conversation}</code> <a class="header-anchor" href="#patch-conversations-conversation" aria-label="Permalink to &quot;PATCH `/conversations/{conversation}`&quot;">​</a></h3><p>Channel <strong>creator</strong> only. Channel name / description / visibility (<code>public</code>|<code>private</code>).</p><h3 id="delete-conversations-conversation" tabindex="-1">DELETE <code>/conversations/{conversation}</code> <a class="header-anchor" href="#delete-conversations-conversation" aria-label="Permalink to &quot;DELETE `/conversations/{conversation}`&quot;">​</a></h3><p>Permanently deletes the channel and all message history (attachments are removed from storage). Requires JSON body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;confirmation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Exact Channel Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>#general</code> cannot be deleted. After delete, the channel name/slug can be reused.</p><h3 id="post-conversations-conversation-join" tabindex="-1">POST <code>/conversations/{conversation}/join</code> <a class="header-anchor" href="#post-conversations-conversation-join" aria-label="Permalink to &quot;POST `/conversations/{conversation}/join`&quot;">​</a></h3><p>Join a <strong>public</strong> channel (idempotent).</p><h3 id="post-conversations-conversation-members" tabindex="-1">POST <code>/conversations/{conversation}/members</code> <a class="header-anchor" href="#post-conversations-conversation-members" aria-label="Permalink to &quot;POST `/conversations/{conversation}/members`&quot;">​</a></h3><p>Body: <code>user_ids</code> (array). Permission: <code>channels.manage</code> + membership.</p><h3 id="delete-conversations-conversation-members-user" tabindex="-1">DELETE <code>/conversations/{conversation}/members/{user}</code> <a class="header-anchor" href="#delete-conversations-conversation-members-user" aria-label="Permalink to &quot;DELETE `/conversations/{conversation}/members/{user}`&quot;">​</a></h3><p>Remove a member. Permission: <code>channels.manage</code> + membership.</p><h3 id="post-conversations-conversation-read" tabindex="-1">POST <code>/conversations/{conversation}/read</code> <a class="header-anchor" href="#post-conversations-conversation-read" aria-label="Permalink to &quot;POST `/conversations/{conversation}/read`&quot;">​</a></h3><p>Marks the conversation read for the actor (<code>last_read_at</code>).</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><h3 id="get-conversations-conversation-messages" tabindex="-1">GET <code>/conversations/{conversation}/messages</code> <a class="header-anchor" href="#get-conversations-conversation-messages" aria-label="Permalink to &quot;GET `/conversations/{conversation}/messages`&quot;">​</a></h3><p>Membership required. Query: <code>before_id</code>, <code>limit</code>, optional <code>parent_id</code> (thread replies).</p><h3 id="post-conversations-conversation-messages" tabindex="-1">POST <code>/conversations/{conversation}/messages</code> <a class="header-anchor" href="#post-conversations-conversation-messages" aria-label="Permalink to &quot;POST `/conversations/{conversation}/messages`&quot;">​</a></h3><p>Body: <code>body</code> (required), optional <code>parent_id</code> (must belong to the same conversation), optional multipart <code>attachments[]</code> (MIME allow-list + max 10 MB each).</p><p>Mention syntax: <code>@[Display Name](user:ID)</code>.</p><h3 id="patch-conversations-conversation-messages-message" tabindex="-1">PATCH <code>/conversations/{conversation}/messages/{message}</code> <a class="header-anchor" href="#patch-conversations-conversation-messages-message" aria-label="Permalink to &quot;PATCH `/conversations/{conversation}/messages/{message}`&quot;">​</a></h3><p>Body: <code>body</code>. Editing re-syncs mention rows (stale mentions are pruned). Soft-delete of a message removes attachment storage objects immediately.</p><h3 id="delete-conversations-conversation-messages-message" tabindex="-1">DELETE <code>/conversations/{conversation}/messages/{message}</code> <a class="header-anchor" href="#delete-conversations-conversation-messages-message" aria-label="Permalink to &quot;DELETE `/conversations/{conversation}/messages/{message}`&quot;">​</a></h3><p>Soft-deletes the message and deletes attachment files from storage.</p><h3 id="reactions-pins" tabindex="-1">Reactions / pins <a class="header-anchor" href="#reactions-pins" aria-label="Permalink to &quot;Reactions / pins&quot;">​</a></h3><ul><li><code>POST/DELETE …/messages/{message}/reactions</code> — body <code>{ &quot;emoji&quot;: &quot;👍&quot; }</code></li><li><code>POST/DELETE …/messages/{message}/pin</code></li><li><code>GET …/conversations/{conversation}/pins</code> — membership required</li></ul><h3 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h3><ul><li><code>POST …/messages/{message}/attachments</code> — multipart <code>attachments[]</code></li><li><code>GET /attachments/{attachment}/download</code> — authenticated download (Bearer / Sanctum); membership on the parent conversation required</li></ul><p>Allowed MIME types include common images, PDF, plain text/CSV, Office docs, and ZIP.</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><h3 id="get-messages-search-q" tabindex="-1">GET <code>/messages/search?q=</code> <a class="header-anchor" href="#get-messages-search-q" aria-label="Permalink to &quot;GET `/messages/search?q=`&quot;">​</a></h3><p>Searches message bodies in conversations the actor belongs to.</p><h2 id="realtime-reverb" tabindex="-1">Realtime (Reverb) <a class="header-anchor" href="#realtime-reverb" aria-label="Permalink to &quot;Realtime (Reverb)&quot;">​</a></h2><p>Private channel: <code>tenant.{tenantId}.conversation.{conversationId}</code></p><p>Join requires membership + matching tenant. Broadcast payloads include message <code>attachments</code> (with <code>download_url</code>) and omit member emails. Typing uses client whispers on the same channel.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Tenant setting <code>team-chat.retention_days</code>: <code>0</code> (forever), <code>30</code>, <code>90</code>, or <code>365</code>.</p><p>Always schedule <code>team-chat:purge-expired</code> in production. When days is <code>0</code> the command is a no-op; otherwise it permanently deletes messages older than the window and their storage objects.</p>',54)])])}const v=a(n,[["render",r]]);export{p as __pageData,v as default};
